use std::sync::atomic::{AtomicU64, AtomicUsize, Ordering};

#[derive(Default)]
pub struct DataBudget {
    bytes: AtomicUsize,
    asof: AtomicU64,
}

impl DataBudget {
    pub fn new(bytes: usize) -> Self {
        Self {
            bytes: AtomicUsize::new(bytes),
            asof: AtomicU64::new(solana_time_utils::timestamp()),
        }

}

pub fn restricted() -> Self {
    Self {
        bytes: AtomicUsize::default(),
        asof: AtomicU64::new(u64::MAX),
    }
}

pub fn get(&self) -> usize {
    self.bytes.load(Ordering::Relaxed)
}

pub fn put(&self, size: usize) -> usize {

    self.bytes.fetch_add(size, Ordering::Relaxed)
}

#[must_use]
pub fn take(&self, size: usize) -> bool {
    let mut bytes = self.bytes.load(Ordering::Acquire);
    loop {
        bytes = match self.bytes.compare_exchange_weak(
            bytes,
            match bytes.checked_sub(size) {
                None => return false,
                Some(bytes) => bytes,
            },
            Ordering::AcqRel,
            Ordering::Acquire,
        ) {
            Ok(_) => return true,
            Err(bytes) => bytes,
        }

